package gen

import (
	"fmt"
	"go/format"
	"strings"

	"github.com/CodeSyncr/nimbus-native/wire/schema"
)

// GoFile is the name of the generated file written into the schema package.
const GoFile = "wire_gen.go"

// Go generates methods on the schema's own types: AppendWire / ReadWire on
// every struct, Append<U> / Read<U> and variant markers for every union, and
// the Message union with Encode / Decode.
func Go(s *schema.Schema) ([]byte, error) {
	g := &goGen{s: s}
	g.p("// Code generated by nimbus-native gen. DO NOT EDIT.\n")
	g.p("package %s\n", s.Package)
	g.p("import (")
	g.p(`"fmt"`)
	if g.usesMaps() {
		g.p(`"slices"`)
	}
	g.p("")
	g.p(`"github.com/CodeSyncr/nimbus-native/wire"`)
	g.p(")\n")

	g.p("// SchemaHash identifies this schema's wire layout. Hosts pass it (combined")
	g.p("// with any other schemas) to nn_start, which refuses a mismatch.")
	g.p("const SchemaHash uint64 = %#016x\n", s.Hash)
	g.p("func init() { wire.Register(%q, SchemaHash) }\n", s.Package)

	for _, st := range s.Structs {
		g.structMethods(st)
	}
	for _, u := range s.Unions {
		g.union(u.Name, u.Marker, u.Variants)
	}

	g.p("// Message is any top-level message in this schema.")
	g.p("type Message interface{ isMessage() }\n")
	g.union(schema.MessageUnion, "isMessage", s.Messages)
	g.p("// Encode returns m's wire encoding: its message id, then its fields.")
	g.p("func Encode(m Message) []byte { return AppendMessage(nil, m) }\n")
	g.p("// Decode reads exactly one message.")
	g.p("func Decode(b []byte) (Message, error) {")
	g.p("r := wire.NewReader(b)")
	g.p("m := ReadMessage(r)")
	g.p("if err := r.Done(); err != nil { return nil, err }")
	g.p("if m == nil { return nil, wire.ErrVariant }")
	g.p("return m, nil")
	g.p("}")

	out, err := format.Source([]byte(g.b.String()))
	if err != nil {
		return nil, fmt.Errorf("gofmt generated code: %w\n%s", err, g.b.String())
	}
	return out, nil
}

type goGen struct {
	s *schema.Schema
	b strings.Builder
}

func (g *goGen) p(format string, args ...any) {
	fmt.Fprintf(&g.b, format, args...)
	g.b.WriteByte('\n')
}

func (g *goGen) usesMaps() bool {
	for _, st := range g.s.Structs {
		for _, f := range st.Fields {
			for t := f.Type; t != nil; t = t.Elem {
				if t.Kind == schema.Map {
					return true
				}
			}
		}
	}
	return false
}

func (g *goGen) structMethods(st *schema.StructDef) {
	g.p("// AppendWire appends m's wire encoding to b.")
	g.p("func (m *%s) AppendWire(b []byte) []byte {", st.Name)
	for _, f := range st.Fields {
		g.write(f.Type, "m."+f.Name, 0)
	}
	g.p("return b")
	g.p("}\n")
	g.p("// ReadWire decodes m from r. Check r.Err() afterwards.")
	g.p("func (m *%s) ReadWire(r *wire.Reader) {", st.Name)
	for _, f := range st.Fields {
		g.read(f.Type, "m."+f.Name, 0)
	}
	g.p("}\n")
}

func (g *goGen) union(name, marker string, variants []string) {
	for _, v := range variants {
		g.p("func (*%s) %s() {}", v, marker)
	}
	g.p("")
	g.p("// Append%s appends a %s: its variant index (0 for nil), then the variant.", name, name)
	g.p("func Append%s(b []byte, v %s) []byte {", name, name)
	g.p("switch v := v.(type) {")
	g.p("case nil:")
	g.p("return append(b, 0)")
	for i, v := range variants {
		g.p("case *%s:", v)
		g.p("return v.AppendWire(wire.AppendUint(b, %d))", i+1)
	}
	g.p("}")
	g.p(`panic(fmt.Sprintf("%s: %%T is not a %s variant", v))`, g.s.Package, name)
	g.p("}\n")
	g.p("// Read%s decodes a %s (nil for index 0).", name, name)
	g.p("func Read%s(r *wire.Reader) %s {", name, name)
	g.p("switch r.Uint() {")
	g.p("case 0:")
	g.p("return nil")
	for i, v := range variants {
		g.p("case %d:", i+1)
		g.p("v := new(%s)", v)
		g.p("v.ReadWire(r)")
		g.p("return v")
	}
	g.p("}")
	g.p("r.Fail(wire.ErrVariant)")
	g.p("return nil")
	g.p("}\n")
}

func (g *goGen) write(t *schema.Type, x string, depth int) {
	switch t.Kind {
	case schema.Bool:
		g.p("b = wire.AppendBool(b, %s)", x)
	case schema.Uint:
		g.p("b = wire.AppendUint(b, uint64(%s))", x)
	case schema.Int:
		g.p("b = wire.AppendInt(b, int64(%s))", x)
	case schema.Float32:
		g.p("b = wire.AppendFloat32(b, %s)", x)
	case schema.Float64:
		g.p("b = wire.AppendFloat64(b, %s)", x)
	case schema.String:
		g.p("b = wire.AppendString(b, %s)", x)
	case schema.Bytes:
		g.p("b = wire.AppendBytes(b, %s)", x)
	case schema.Enum:
		if t.Signed {
			g.p("b = wire.AppendInt(b, int64(%s))", x)
		} else {
			g.p("b = wire.AppendUint(b, uint64(%s))", x)
		}
	case schema.Struct:
		g.p("b = %s.AppendWire(b)", x)
	case schema.Union:
		g.p("b = Append%s(b, %s)", t.Name, x)
	case schema.Optional:
		g.p("if %s == nil {", x)
		g.p("b = append(b, 0)")
		g.p("} else {")
		g.p("b = append(b, 1)")
		if t.Elem.Kind == schema.Struct {
			g.write(t.Elem, x, depth)
		} else {
			g.write(t.Elem, "*"+x, depth)
		}
		g.p("}")
	case schema.List:
		v := fmt.Sprintf("v%d", depth)
		g.p("b = wire.AppendUint(b, uint64(len(%s)))", x)
		g.p("for _, %s := range %s {", v, x)
		g.write(t.Elem, v, depth+1)
		g.p("}")
	case schema.Map:
		k, v, keys := fmt.Sprintf("k%d", depth), fmt.Sprintf("v%d", depth), fmt.Sprintf("keys%d", depth)
		g.p("{")
		g.p("b = wire.AppendUint(b, uint64(len(%s)))", x)
		g.p("%s := make([]%s, 0, len(%s))", keys, t.Key.GoType, x)
		g.p("for %s := range %s {", k, x)
		g.p("%s = append(%s, %s)", keys, keys, k)
		g.p("}")
		g.p("slices.Sort(%s)", keys)
		g.p("for _, %s := range %s {", k, keys)
		g.write(t.Key, k, depth+1)
		g.p("%s := %s[%s]", v, x, k)
		g.write(t.Elem, v, depth+1)
		g.p("}")
		g.p("}")
	}
}

func (g *goGen) read(t *schema.Type, x string, depth int) {
	switch t.Kind {
	case schema.Bool:
		g.p("%s = r.Bool()", x)
	case schema.Uint:
		if t.Bits == 64 {
			g.p("%s = %s(r.Uint())", x, t.GoType)
		} else {
			g.p("%s = %s(r.UintMax(1<<%d - 1))", x, t.GoType, t.Bits)
		}
	case schema.Int:
		g.readInt(t.Bits, t.GoType, x)
	case schema.Float32:
		g.p("%s = r.Float32()", x)
	case schema.Float64:
		g.p("%s = r.Float64()", x)
	case schema.String:
		g.p("%s = r.String()", x)
	case schema.Bytes:
		g.p("%s = r.Bytes()", x)
	case schema.Enum:
		switch {
		case t.Signed:
			g.readInt(t.Bits, t.Name, x)
		case t.Bits == 64:
			g.p("%s = %s(r.Uint())", x, t.Name)
		default:
			g.p("%s = %s(r.UintMax(1<<%d - 1))", x, t.Name, t.Bits)
		}
	case schema.Struct:
		if strings.HasPrefix(t.GoType, "*") {
			g.p("%s = new(%s)", x, t.Name)
		}
		g.p("%s.ReadWire(r)", x)
	case schema.Union:
		g.p("%s = Read%s(r)", x, t.Name)
	case schema.Optional:
		g.p("if r.Bool() {")
		if t.Elem.Kind == schema.Struct {
			g.p("%s = new(%s)", x, t.Elem.Name)
			g.p("%s.ReadWire(r)", x)
		} else {
			v := fmt.Sprintf("o%d", depth)
			g.p("var %s %s", v, t.Elem.GoType)
			g.read(t.Elem, v, depth+1)
			g.p("%s = &%s", x, v)
		}
		g.p("}")
	case schema.List:
		n, i, v := fmt.Sprintf("n%d", depth), fmt.Sprintf("i%d", depth), fmt.Sprintf("v%d", depth)
		g.p("if %s := r.Count(); %s > 0 {", n, n)
		g.p("%s = make(%s, 0, wire.Cap(%s))", x, t.GoType, n)
		g.p("for %s := 0; %s < %s && r.Err() == nil; %s++ {", i, i, n, i)
		g.p("var %s %s", v, t.Elem.GoType)
		g.read(t.Elem, v, depth+1)
		g.p("%s = append(%s, %s)", x, x, v)
		g.p("}")
		g.p("}")
	case schema.Map:
		n, i, k, v := fmt.Sprintf("n%d", depth), fmt.Sprintf("i%d", depth), fmt.Sprintf("k%d", depth), fmt.Sprintf("v%d", depth)
		g.p("if %s := r.Count(); %s > 0 {", n, n)
		g.p("%s = make(%s, wire.Cap(%s))", x, t.GoType, n)
		g.p("for %s := 0; %s < %s && r.Err() == nil; %s++ {", i, i, n, i)
		g.p("var %s %s", k, t.Key.GoType)
		g.read(t.Key, k, depth+1)
		g.p("var %s %s", v, t.Elem.GoType)
		g.read(t.Elem, v, depth+1)
		g.p("%s[%s] = %s", x, k, v)
		g.p("}")
		g.p("}")
	}
}

func (g *goGen) readInt(bits int, goType, x string) {
	if bits == 64 {
		g.p("%s = %s(r.Int())", x, goType)
		return
	}
	g.p("%s = %s(r.IntRange(-1<<%d, 1<<%d-1))", x, goType, bits-1, bits-1)
}
